    L_vine = rd([&]() -> V { V out_ = V::list(); V L_p; { V it1_ = py::iter_list(m_at(Args{L_b, V(5.0), V(9.0)})); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_p = it1_.idx(int64_t(i1_)); if (!((py::m_get_slot(L_p, &Obj::_pvp_content, SV("_pvp_content")) == SV("阳光藤蔓")))) continue; out_.append(L_p); }}return out_; }(), V(0.0));
