V C_PvP58Tests::m_test_petrified_vine_takes_every_status_exactly_like_a_brain_grave(const Args& A) {
    V L_b;
    V L_effect;
    V L_grave;
    V L_hp;
    V L_key;
    V L_results;
    V L_row;
    V L_status;
    V L_uid;
    V L_vine;
    L_results = py_dict({});
    { V it1_ = py::iter_list(V::tuple({SV("zombie:石化藤蔓"), SV("zombie:脑光墓碑")}));
    for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) {
        L_key = it1_.idx(int64_t(i1_)); 
        L_row = py_dict({});
        { V it2_ = py::iter_list(V::tuple({SV("none"), SV("slow"), SV("freeze"), SV("butter"), SV("stun"), SV("poison")}));
        for (size_t i2_ = 0; i2_ < it2_.len(); ++i2_) {
            L_status = it2_.idx(int64_t(i2_)); 
            L_b = m_battle(Args({}, {{SY("zombies"), V::list({L_key, SV("zombie:普通僵尸")})}}));
            (void)(m_assertEqual(Args{SV(""), m_dep(Args{L_b, SV("zombie"), L_key, V(20.0), V(9.0)})}));
            L_uid = py::next([&]() -> V { V out_ = V::list(); V L_u; { V it3_ = py::iter_list(pvz::getattr(L_b, SY("units"))); for (size_t i3_ = 0; i3_ < it3_.len(); ++i3_) { L_u = it3_.idx(int64_t(i3_)); if (!((rd(rd(pvz::getattr(L_b, SY("units")), L_u), SV("card_id")) == L_key))) continue; out_.append(L_u); }}return out_; }());
            L_grave = rd(pvz::getattr(L_b, SY("_native_objects")), L_uid);
            pvz::setitem(L_grave, SV("_pvp_produced"), V(true));
            pvz::setattr(pvz::getattr(L_b, SY("protection")), SY("until"), V(0.0));
            L_hp = rdm(L_grave, &Obj::血量, SV("血量"));
            L_effect = py::m_get(py_dict({{SV("slow"), V::tuple({SV("冰冻"), V(900.0)})}, {SV("freeze"), V::tuple({SV("冰冻"), V(100000.0)})}, {SV("butter"), V::tuple({SV("黄油"), V(100000.0)})}, {SV("stun"), V::tuple({SV("眩晕"), V(100000.0)})}}), L_status);
            if ((L_effect).truthy()) {
                pvz::setitem(L_grave, rd(L_effect, V(0.0)), rd(L_effect, V(1.0)));
            }
            if ((L_status == SV("poison"))) {
                (void)(callm(pvz::getattr(L_b, SY("status")), SY("apply"), Args{L_grave, V(1.0), V(3.0)}));
            }
            (void)(callm(L_b, SY("step"), Args{V(30.0)}));
            pvz::setitem(L_row, L_status, V::tuple({py::round(py::m_get_slot(L_grave, &Obj::_pvp_production_rate, SV("_pvp_production_rate"), V(1.0)), V(2.0)), py::round((L_hp - rdm(L_grave, &Obj::血量, SV("血量"))), V(2.0))}));
            (void)(m_retire_battle(Args{L_b}));
            L_grave.del();
            L_b.del();
            (void)(py::stdlib_call(SV("gc.collect"), Args{}));
        }}
        pvz::setitem(L_results, L_key, L_row);
    }}
    (void)(m_assertEqual(Args{rd(L_results, SV("zombie:脑光墓碑")), rd(L_results, SV("zombie:石化藤蔓"))}));
    L_vine = rd(L_results, SV("zombie:石化藤蔓"));
    (void)(m_assertEqual(Args{V(0.5), rd(rd(L_vine, SV("slow")), V(0.0))}));
    (void)(m_assertEqual(Args{V(0.0), rd(rd(L_vine, SV("freeze")), V(0.0))}));
    (void)(m_assertEqual(Args{V(0.0), rd(rd(L_vine, SV("butter")), V(0.0))}));
    (void)(m_assertEqual(Args{V(0.0), rd(rd(L_vine, SV("stun")), V(0.0))}));
    (void)(m_assertGreater(Args{rd(rd(L_vine, SV("poison")), V(1.0)), V(0.0)}));
    return V::none();
}

